        },
        "key": {
          "type": "string",
          "maxLength": 64,
          "minLength": 1,
          "pattern": "^[a-z][a-z0-9_]*$",
          "title": "Key",
          "description": "Lowercase slug used as metric key (e.g. 'voice_quality_score')"
        },
        "name": {
          "type": "string",
          "maxLength": 256,
          "minLength": 1
        },
        "description": {
          "type": "string",
          "maxLength": 2000
        },
        "metric_type": {
          "type": "string",
          "enum": [
            "numerical",
            "categorical",
            "boolean"
          ],
          "title": "Metric Type"
        },
